/* Card set: World Landmarks (generated from the approved roster-final.csv by the Landmarks build, schema per tools/csv-to-set.js).
   (world-landmarks.js exceeds the comfortable push size, so the remaining cards live in
   world-landmarks-additions.js, which must stay directly after 'world-landmarks.js' in sets/manifest.js.) */
CardSets.register({"id":"world-landmarks","name":"World Landmarks","code":"LAND","description":"420 cards of the world's great human-made landmarks — monuments and memorials, bridges, towers, castles, ancient sites and famous buildings.","theme":{"primary":"#7a4e1d","secondary":"#c9a227","artBackground":"#f4ecdd","artFit":"cover"},"pack":{"name":"World Landmarks Pack","emblem":"🏛️","skin":"world-landmarks"},"cards":[{"name":"Eiffel Tower","rarity":"chase","id":"eiffel-tower","subtitle":"Tower","details":"Designed by Gustave Eiffel for the 1889 World's Fair in Paris, the iron lattice tower stands 330 metres tall and was the world's tallest structure for 41 years.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tour_Eiffel_Wikimedia_Commons_%28cropped%29.jpg?width=1024"},{"name":"Statue of Liberty","rarity":"chase","id":"statue-of-liberty","subtitle":"Statue","details":"A gift from France dedicated in 1886, Bartholdi's copper statue rises 93 metres over New York Harbor, holding a torch and a tablet dated July 4, 1776.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Front_view_of_Statue_of_Liberty_%28cropped%29.jpg?width=1024"},{"name":"Great Wall of China","rarity":"chase","id":"great-wall-of-china","subtitle":"Ancient Site","details":"Built and rebuilt by Chinese states and dynasties from the 7th century BC onward, its stone and rammed-earth walls snake across China's northern frontier.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/The_Great_Wall_of_China_at_Jinshanling-edit.jpg?width=1024"},{"name":"Taj Mahal","rarity":"chase","id":"taj-mahal","subtitle":"Monument","details":"Shah Jahan commissioned this white marble mausoleum in Agra in 1632 for his wife Mumtaz Mahal; its dome, minarets and inlay took two decades to complete.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Taj_Mahal_%28Edited%29.jpeg?width=1024"},{"name":"Colosseum","rarity":"chase","id":"colosseum","subtitle":"Ancient Site","details":"Rome's great elliptical amphitheatre, built of travertine and concrete in AD 80, seated some 50,000 spectators for gladiator contests and public spectacles.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Colosseo_2020.jpg?width=1024"},{"name":"Pyramids of Giza","rarity":"chase","id":"pyramids-of-giza","subtitle":"Ancient Site","details":"Raised around 2560 BC as royal tombs for the pharaohs Khufu, Khafre and Menkaure, the Giza pyramids were built from millions of limestone and granite blocks.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pyramids_of_the_Giza_Necropolis.jpg?width=1024"},{"name":"Big Ben (Elizabeth Tower)","rarity":"chase","id":"big-ben","subtitle":"Tower","details":"The Elizabeth Tower at London's Palace of Westminster, completed in 1859, houses Great Bell Big Ben, whose name the whole 96-metre tower is known by worldwide.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Elizabeth_Tower_and_the_north_front_of_the_Palace_of_Westminster%2C_London.jpg?width=1024"},{"name":"Golden Gate Bridge","rarity":"chase","id":"golden-gate-bridge","subtitle":"Bridge","details":"Completed in 1937, this suspension bridge spans the Golden Gate Strait in San Francisco, its International Orange towers rising 227 metres above the bay.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bf/Golden_Gate_Bridge_as_seen_from_Battery_East.jpg/1280px-Golden_Gate_Bridge_as_seen_from_Battery_East.jpg"},{"name":"Sydney Opera House","rarity":"chase","id":"sydney-opera-house","subtitle":"Building","details":"Opened in 1973 on Bennelong Point in Sydney Harbour, its white sail-like shells, designed by Jorn Utzon, made it an enduring symbol of Australia.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sydney%20Opera%20House%20-%20Dec%202008.jpg?width=1024"},{"name":"Machu Picchu","rarity":"chase","id":"machu-picchu","subtitle":"Ancient Site","details":"A 15th-century Inca estate in the Peruvian Andes, Machu Picchu was built with precisely cut dry-stone walls, temples and terraces high above the Urubamba River.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Machu_Picchu%2C_2023_%28012%29.jpg?width=1024"},{"name":"Lincoln Memorial","rarity":"legendary","id":"lincoln-memorial","subtitle":"Memorial","details":"Dedicated in 1922, Henry Bacon's Doric temple in Washington holds Daniel Chester French's seated marble Lincoln, flanked by two of his speeches.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Lincoln_Memorial_east_side.JPG?width=1024"},{"name":"Mount Rushmore","rarity":"legendary","id":"mount-rushmore","subtitle":"Monument","details":"Gutzon Borglum and 400 workers carved the 18-metre faces of Washington, Jefferson, Roosevelt and Lincoln into South Dakota granite between 1927 and 1941.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mount_Rushmore_detail_view_%28100MP%29.jpg?width=1024"},{"name":"Christ the Redeemer","rarity":"legendary","id":"christ-the-redeemer","subtitle":"Statue","details":"Completed in 1931 atop Rio's Corcovado Mountain, this Art Deco statue of Jesus stands 30 metres tall, its arms stretching 28 metres in soapstone and concrete.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Christ_the_Redeemer_-_Cristo_Redentor.jpg?width=800"},{"name":"Arc de Triomphe","rarity":"legendary","id":"arc-de-triomphe","subtitle":"Monument","details":"Commissioned by Napoleon in 1806 and finished in 1836, this 50-metre Paris arch honours France's armies, their generals and victories carved into its faces.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Arc_de_Triomphe_-_Ao%C3%BBt_2026.jpg?width=1024"},{"name":"Washington Monument","rarity":"legendary","id":"washington-monument","subtitle":"Monument","details":"Finished in 1884, this 169-metre marble obelisk in Washington honours George Washington; its shade changes where construction paused for two decades.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Washington_Monument_2022.jpg?width=1024"},{"name":"Brooklyn Bridge","rarity":"legendary","id":"brooklyn-bridge","subtitle":"Bridge","details":"Opened in 1883, the Brooklyn Bridge carries traffic across New York's East River, a steel-wire suspension design with distinctive Gothic stone towers.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f0/Brooklyn_Bridge_and_the_Lower_Manhattan_skyline_from_Pebble_Beach%2C_New_York.jpg/1280px-Brooklyn_Bridge_and_the_Lower_Manhattan_skyline_from_Pebble_Beach%2C_New_York.jpg"},{"name":"Tower Bridge","rarity":"legendary","id":"tower-bridge","subtitle":"Bridge","details":"London's Tower Bridge, completed in 1894, combines bascules and suspension spans across the River Thames, its twin towers clad in pale stone and steel.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/59/Tower_Bridge_at_Dawn.jpg/1280px-Tower_Bridge_at_Dawn.jpg"},{"name":"Sydney Harbour Bridge","rarity":"legendary","id":"sydney-harbour-bridge","subtitle":"Bridge","details":"Sydney Harbour Bridge, opened in 1932, is a steel through-arch carrying road and rail across the harbour, nicknamed the Coathanger for its curved profile.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/55/Sydney_Harbour_Bridge-16_October_2025.jpg/1280px-Sydney_Harbour_Bridge-16_October_2025.jpg"},{"name":"Millau Viaduct","rarity":"legendary","id":"millau-viaduct","subtitle":"Bridge","details":"The Millau Viaduct in southern France, opened in 2004, carries the A75 motorway over the Tarn gorge on seven slender pylons of a cable-stayed design.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/00%200237%20Millau%20-%20D%C3%A9partement%20Aveyron.jpg?width=1024"},{"name":"Burj Khalifa","rarity":"legendary","id":"burj-khalifa","subtitle":"Tower","details":"Dubai's Burj Khalifa, designed by Adrian Smith and completed in 2010, rises 828 metres over 163 floors in a spiralling footprint inspired by a desert flower.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Burj%20Khalifa%20and%20surrounding%20buildings%20during%20sunset.jpg?width=1024"},{"name":"Empire State Building","rarity":"legendary","id":"empire-state-building","subtitle":"Skyscraper","details":"New York's Empire State Building, an Art Deco icon completed in 1931 after just 13 months of construction, stands 443 metres tall including its antenna spire.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Empire%20State%20Building%20by%20David%20Shankbone.jpg?width=1024"},{"name":"CN Tower","rarity":"legendary","id":"cn-tower","subtitle":"Tower","details":"Toronto's CN Tower, completed in 1976, is a 553-metre concrete communications tower with a glass-floor observation deck 342 metres above the city streets.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Toronto%20-%20ON%20-%20CN%20Tower%20bei%20Nacht.jpg?width=1024"},{"name":"Tokyo Skytree","rarity":"legendary","id":"tokyo-skytree","subtitle":"Tower","details":"Tokyo Skytree, completed in 2012, is a 634-metre broadcasting tower whose height echoes the old Musashi province number 634, read as 'mu-sa-shi' in Japanese.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tokyo_Skytree_2014_%E2%85%A2.jpg?width=1024"},{"name":"Shanghai Tower","rarity":"legendary","id":"shanghai-tower","subtitle":"Skyscraper","details":"Shanghai Tower, completed in 2015, twists as it rises 632 metres, its transparent outer skin and cylindrical inner tower working together to cut wind loads.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/20191114_Shanghai_Tower_%282%29.jpg?width=1024"},{"name":"Leaning Tower of Pisa","rarity":"legendary","id":"leaning-tower-of-pisa","subtitle":"Tower","details":"The Leaning Tower of Pisa, a freestanding campanile begun in 1173, tilts because its shallow foundations settled into soft soil on one side during building.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Italy_-_Pisa_-_Leaning_Tower.jpg?width=800"},{"name":"Neuschwanstein Castle","rarity":"legendary","id":"neuschwanstein-castle","subtitle":"Castle","details":"Commissioned by Ludwig II of Bavaria in 1868 above the Pollat Gorge, this Romanesque Revival palace of turrets and frescoed halls inspired a fairytale castle.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Schloss_Neuschwanstein_2013.jpg?width=1024"},{"name":"Palace of Versailles","rarity":"legendary","id":"palace-of-versailles","subtitle":"Palace","details":"Louis XIV transformed his father's hunting lodge into this vast Baroque palace from 1661, centred on the Hall of Mirrors and gardens laid out by Andre Le Notre.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Vue_a%C3%A9rienne_du_domaine_de_Versailles_par_ToucanWings_-_Creative_Commons_By_Sa_3.0_-_081_%28cropped%29.jpg?width=1024"},{"name":"Buckingham Palace","rarity":"legendary","id":"buckingham-palace","subtitle":"Palace","details":"The London residence of the British monarch, this palace grew from Buckingham House of 1703 and gained its famous east front and balcony in the 1800s.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Buckingham_Palace_London_Morning_2020_01_%28cropped%29.jpg?width=1024"},{"name":"Edinburgh Castle","rarity":"legendary","id":"edinburgh-castle","subtitle":"Castle","details":"Perched on Castle Rock above the city, this fortress anchored Scottish royal power for centuries and holds the Honours of Scotland and the Stone of Destiny.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/City_of_Edinburgh_-_Edinburgh_Castle_-_20140421004403.jpg?width=1024"},{"name":"Himeji Castle","rarity":"legendary","id":"himeji-castle","subtitle":"Castle","details":"Japan's finest surviving feudal castle, this white-plastered keep complex from 1609 earned the name White Heron Castle for its elegant, birdlike silhouette.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Himeji_castle_in_may_2015.jpg?width=1024"},{"name":"Forbidden City","rarity":"legendary","id":"forbidden-city","subtitle":"Palace","details":"Built in Beijing from 1406 to 1420, this walled palace of nearly a thousand buildings housed Ming and Qing emperors as the ceremonial heart of imperial China.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hall%20of%20Supreme%20Harmony.JPG?width=1024"},{"name":"Stonehenge","rarity":"legendary","id":"stonehenge","subtitle":"Ancient Site","details":"Raised on Salisbury Plain in stages between about 3000 and 2000 BC, Stonehenge arranges massive sarsen and bluestone pillars in a prehistoric circular setting.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Stonehenge2007_07_30.jpg?width=1024"},{"name":"Parthenon","rarity":"legendary","id":"parthenon","subtitle":"Ancient Site","details":"Built in Athens between 447 and 432 BC, the Parthenon was a marble temple to the goddess Athena, famed for its refined columns and classical proportions.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/The_Parthenon_in_Athens.jpg?width=1024"},{"name":"Angkor Wat","rarity":"legendary","id":"angkor-wat","subtitle":"Ancient Site","details":"Built in the early 12th century by the Khmer king Suryavarman II, Angkor Wat in Cambodia is a vast temple complex of sandstone galleries and lotus-like towers.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Angkor_Wat.jpg?width=1024"},{"name":"Petra","rarity":"legendary","id":"petra","subtitle":"Ancient Site","details":"Carved into rose-red sandstone cliffs by the Nabataeans from the 1st century BC, Petra in Jordan was a caravan city famed for the Treasury's ornate facade.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Al_Deir_Petra.JPG?width=1024"},{"name":"Chichen Itza","rarity":"legendary","id":"chichen-itza","subtitle":"Ancient Site","details":"A Maya city on Mexico's Yucatan Peninsula, Chichen Itza flourished from about AD 600, crowned by El Castillo, a step pyramid aligned with the equinox sun.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Chichen_Itza_3.jpg?width=1024"},{"name":"St. Peter's Basilica","rarity":"legendary","id":"st-peters-basilica","subtitle":"Cathedral","details":"Completed in 1626 in Vatican City, this Renaissance basilica stands over the traditional tomb of St. Peter, with a dome designed by Michelangelo.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Basilica%20Sancti%20Petri%20blue%20hour.jpg?width=1024"},{"name":"Sagrada Familia","rarity":"legendary","id":"sagrada-familia","subtitle":"Building","details":"Antoni Gaudi's great Barcelona basilica, begun in 1882, blends Gothic and Art Nouveau forms in soaring stone towers and richly sculpted facades.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/SF%20maig%202%20cropped.jpg?width=800"},{"name":"Hagia Sophia","rarity":"legendary","id":"hagia-sophia","subtitle":"Cathedral","details":"Built in Constantinople in 537 under Emperor Justinian I, this vast domed basilica served as cathedral, mosque and museum across its long history.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hagia%20Sophia%20Mars%202013.jpg?width=1024"},{"name":"Notre-Dame de Paris","rarity":"legendary","id":"notre-dame-de-paris","subtitle":"Cathedral","details":"This Gothic cathedral on the Ile de la Cite in Paris, begun in 1163, is famed for its flying buttresses, twin towers and great rose windows.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Notre%20Dame%20Paris%20front%20facade%20lower.jpg?width=1024"},{"name":"Gateway Arch","rarity":"epic","id":"gateway-arch","subtitle":"Monument","details":"Eero Saarinen's stainless steel arch in St. Louis, completed in 1965, rises 192 metres over the Mississippi, its legs as wide as the arch is tall.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/St_Louis_night_expblend_cropped.jpg?width=1024"},{"name":"Statue of Unity","rarity":"epic","id":"statue-of-unity","subtitle":"Monument","details":"Unveiled in Gujarat in 2018, this statue of Sardar Vallabhbhai Patel stands 182 metres tall in bronze-clad concrete beside the Narmada River.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Statue_of_Unity.jpg?width=1024"},{"name":"Leshan Giant Buddha","rarity":"epic","id":"leshan-giant-buddha","subtitle":"Statue","details":"Carved into a Sichuan cliff between 713 and 803, this Tang dynasty stone Buddha sits 71 metres tall where three rivers meet below it.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Leshan%20Giant%20Buddha%20View%20from%20below.jpg?width=1024"},{"name":"Spring Temple Buddha","rarity":"epic","id":"spring-temple-buddha","subtitle":"Statue","details":"Completed in Henan in 2008, this copper statue of Vairocana Buddha rises 128 metres from its lotus throne in the foothills of Lushan.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Spring_Temple_Buddha_picturing_Vairocana%2C_in_Lushan_County%2C_Henan%2C_China.png?width=1024"},{"name":"Moai Statues","rarity":"epic","id":"moai-statues","subtitle":"Statue","details":"The Rapa Nui carved these monolithic stone figures on Easter Island between about 1250 and 1500; nearly 1,000 moai survive, the heaviest at 86 tonnes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/AhuTongariki.JPG?width=1024"},{"name":"The Motherland Calls","rarity":"epic","id":"the-motherland-calls","subtitle":"Statue","details":"Raised in Volgograd in 1967, this 85-metre concrete figure of a sword-wielding woman honours the defenders of Stalingrad, her robes swept back mid-stride.","image":"https://en.wikipedia.org/wiki/Special:FilePath/The_Motherland_Calls_detail_-_Volgograd%2C_October_2018.jpg?width=1024"},{"name":"Ushiku Daibutsu","rarity":"epic","id":"ushiku-daibutsu","subtitle":"Statue","details":"Cast in bronze and completed in 1993 in Ibaraki, Japan, this statue of Amida Buddha stands 120 metres tall, its left hand raised in blessing.","image":"https://en.wikipedia.org/wiki/Special:FilePath/Ushiku.jpg?width=1024"},{"name":"Garuda Wisnu Kencana","rarity":"epic","id":"garuda-wisnu-kencana","subtitle":"Monument","details":"Completed in Bali in 2018, Nyoman Nuarta's copper and steel statue shows Vishnu riding the bird Garuda, standing 121 metres with its base.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Patung_Garuda_Wisnu_Kencana.jpg?width=1024"},{"name":"Akashi Kaikyo Bridge","rarity":"epic","id":"akashi-kaikyo-bridge","subtitle":"Bridge","details":"Japan's Akashi Kaikyo Bridge, completed in 1998, links Kobe with Awaji Island across the Akashi Strait on a main suspension span of 1,991 metres.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c6/%E6%98%8E%E7%9F%B3%E6%B5%B7%E5%B3%A1%E5%A4%A7%E6%A9%8B_-_panoramio_%281%29_%28cropped%29.jpg/1280px-%E6%98%8E%E7%9F%B3%E6%B5%B7%E5%B3%A1%E5%A4%A7%E6%A9%8B_-_panoramio_%281%29_%28cropped%29.jpg"},{"name":"Humber Bridge","rarity":"epic","id":"humber-bridge","subtitle":"Bridge","details":"The Humber Bridge, opened in 1981 near Hull in England, crosses the Humber estuary on a single suspension span of 1,410 metres between concrete towers.","image":"https://upload.wikimedia.org/wikipedia/commons/b/b7/Humber_Br%C3%A9ck_zu_Hull_w.jpg"},{"name":"George Washington Bridge","rarity":"epic","id":"george-washington-bridge","subtitle":"Bridge","details":"New York's George Washington Bridge, designed by Othmar Ammann and opened in 1931, carries traffic over the Hudson River on two stacked roadway decks.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ab/GWBfromFortLeeHistoricPark.JPG/1280px-GWBfromFortLeeHistoricPark.JPG"},{"name":"Rialto Bridge","rarity":"epic","id":"rialto-bridge","subtitle":"Bridge","details":"Venice's Rialto Bridge, a stone arch completed in 1591, crosses the Grand Canal at its narrowest point, lined with shops along its covered central walkway.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0b/Rialto_2025_4.jpg/1280px-Rialto_2025_4.jpg"},{"name":"Ponte Vecchio","rarity":"epic","id":"ponte-vecchio","subtitle":"Bridge","details":"Florence's Ponte Vecchio, rebuilt in stone in 1345, crosses the Arno on three segmental arches, carrying jewellers' shops and the Vasari Corridor above.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7d/Ponte_Vecchio_from_Ponte_alle_Grazie.jpg/1280px-Ponte_Vecchio_from_Ponte_alle_Grazie.jpg"},{"name":"Charles Bridge","rarity":"epic","id":"charles-bridge","subtitle":"Bridge","details":"Prague's Charles Bridge, begun in 1357 under Charles IV, crosses the Vltava on sixteen stone arches, later lined with statues of saints along both sides.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/22/Prague_07-2016_view_from_Lesser_Town_Tower_of_Charles_Bridge_img3.jpg/1280px-Prague_07-2016_view_from_Lesser_Town_Tower_of_Charles_Bridge_img3.jpg"},{"name":"Chrysler Building","rarity":"epic","id":"chrysler-building","subtitle":"Skyscraper","details":"The Chrysler Building, completed in 1930, hid a surprise: its stainless-steel Art Deco crown and spire were assembled in secret to win a height race.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Chrysler%20Building%20%281%29.jpg?width=1024"},{"name":"Taipei 101","rarity":"epic","id":"taipei-101","subtitle":"Skyscraper","details":"Taipei 101, completed in 2004, stacks eight pagoda-like segments of eight floors each and hides a 660-tonne tuned mass damper that sways against typhoon winds.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Taipei%20101%202009%20amk.jpg?width=1024"},{"name":"Petronas Towers","rarity":"epic","id":"petronas-towers","subtitle":"Tower","details":"Kuala Lumpur's Petronas Towers, completed in 1998, are twin 452-metre towers joined by a double-decker skybridge, their facades patterned on Islamic geometry.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Petronas%20Towers%2C%20Kuala%20Lumpur%20%283323152170%29.jpg?width=1024"},{"name":"Oriental Pearl Tower","rarity":"epic","id":"oriental-pearl-tower","subtitle":"Tower","details":"Shanghai's Oriental Pearl Tower, completed in 1994, strings eleven spheres of pink-tinted glass along a 468-metre frame inspired by a Tang dynasty poem.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Oriental_Pearl_Tower_20251126.jpg?width=1024"},{"name":"Space Needle","rarity":"epic","id":"space-needle","subtitle":"Tower","details":"Seattle's Space Needle, built for the 1962 World's Fair, stands 184 metres tall with a rotating restaurant and a flying-saucer top designed for the Space Age.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Space_Needle_2011-07-04.jpg?width=1024"},{"name":"One World Trade Center","rarity":"epic","id":"one-world-trade-center","subtitle":"Skyscraper","details":"One World Trade Center, completed in 2014 on the World Trade Center site in New York, rises a symbolic 1,776 feet, matching the year of American independence.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/One%20World%20Trade%20Center%2C%20Financial%20District%2C%20Manhattan%2C%20New%20York.jpg?width=1024"},{"name":"The Shard","rarity":"epic","id":"the-shard","subtitle":"Tower","details":"London's Shard, designed by Renzo Piano and completed in 2012, is a 310-metre glass pyramid of offices, flats and a hotel tapering to a jagged, open point.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/The_Shard_at_sunset_2017_%28cropped%29.jpg?width=1024"},{"name":"Ostankino Tower","rarity":"epic","id":"ostankino-tower","subtitle":"Tower","details":"Moscow's Ostankino Tower, completed in 1967, is a 540-metre concrete broadcasting tower that stood as the world's tallest freestanding structure for nine years.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/%D0%9E%D1%81%D1%82%D0%B0%D0%BD%D0%BA%D0%B8%D0%BD%D1%81%D0%BA%D0%B0%D1%8F_%D0%B1%D0%B0%D1%88%D0%BD%D1%8F_%D0%B2%D0%B5%D1%87%D0%B5%D1%80%D0%BE%D0%BC.jpg?width=1024"},{"name":"Windsor Castle","rarity":"epic","id":"windsor-castle","subtitle":"Castle","details":"Founded by William the Conqueror around 1070 beside the Thames, this royal fortress grew into a sprawling palace anchored by St George's Chapel.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Windsor_Castle_at_Sunset_-_Nov_2006.jpg?width=1024"},{"name":"Tower of London","rarity":"epic","id":"tower-of-london","subtitle":"Castle","details":"William the Conqueror raised the White Tower in 1078, and the Norman keep grew into a fortress, royal palace and prison guarding the Crown Jewels.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tower_of_London_from_the_Shard_%288515883950%29.jpg?width=1024"},{"name":"Alhambra","rarity":"epic","id":"alhambra","subtitle":"Palace","details":"The Nasrid sultans of Granada built this fortified palace city in the 1200s and 1300s, famed for carved stucco, tilework and the Court of the Lions.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dawn_Charles_V_Palace_Alhambra_Granada_Andalusia_Spain.jpg?width=1024"},{"name":"Schonbrunn Palace","rarity":"epic","id":"schonbrunn-palace","subtitle":"Palace","details":"Vienna's great imperial summer residence took Baroque form under Maria Theresa, with 1,441 rooms, a vast park and the hilltop Gloriette overlooking the capital.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Wien_-_Schloss_Sch%C3%B6nbrunn.JPG?width=1024"},{"name":"Peterhof Palace","rarity":"epic","id":"peterhof-palace","subtitle":"Palace","details":"Peter the Great founded this Baltic palace ensemble in 1714, celebrated for its Grand Cascade of gilded fountains stepping from the palace terrace to the sea.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Peterhof_Palace%2C_Saint_Petersburg%2C_Russia_%2844408938295%29.jpg?width=1024"},{"name":"Prague Castle","rarity":"epic","id":"prague-castle","subtitle":"Castle","details":"Founded in the ninth century above the Vltava, this vast castle district centres on St Vitus Cathedral and has seated Bohemian kings, emperors and presidents.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Karl%C5%AFv_most_Praha%2C_Star%C3%A9_M%C4%9Bsto_20170810_007.jpg?width=1024"},{"name":"Bran Castle","rarity":"epic","id":"bran-castle","subtitle":"Castle","details":"Built by the Teutonic Knights and Saxon townsfolk in the 1300s on a Transylvanian crag, this castle became linked in legend with Bram Stoker's Dracula.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Castelul_Bran2.jpg?width=1024"},{"name":"Pena Palace","rarity":"epic","id":"pena-palace","subtitle":"Palace","details":"King Ferdinand II created this vivid Romanticist palace in the 1840s on a Sintra hilltop, mixing red and yellow towers, Manueline carving and forested parkland.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sintra_-_Palacio_da_Pena_%2820332995770%29.jpg?width=1024"},{"name":"Pantheon","rarity":"epic","id":"pantheon","subtitle":"Ancient Site","details":"Rebuilt in Rome around AD 126 under Hadrian, the Pantheon pairs a Corinthian portico with a vast unreinforced concrete dome pierced by a central oculus.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pantheon_%28Rome%29_-_Right_side_and_front.jpg?width=1024"},{"name":"Terracotta Army","rarity":"epic","id":"terracotta-army","subtitle":"Ancient Site","details":"Thousands of life-size clay soldiers, horses and chariots were buried near Xi'an around 210 BC to guard the tomb of China's first emperor, Qin Shi Huang.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/51714-Terracota-Army.jpg?width=1024"},{"name":"Borobudur","rarity":"epic","id":"borobudur","subtitle":"Ancient Site","details":"Built in Java around AD 800 from grey volcanic stone, Borobudur is a vast Buddhist monument of terraced levels, relief panels and perforated bell stupas.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pradaksina.jpg?width=1024"},{"name":"Baalbek","rarity":"epic","id":"baalbek","subtitle":"Ancient Site","details":"In Lebanon's Bekaa Valley, Baalbek preserves colossal Roman temples, including the Temple of Jupiter, raised on some of the largest stone blocks ever quarried.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Temple_of_Bacchus%2C_Baalbek%2C_Lebanon_%2849890013476%29.jpg?width=1024"},{"name":"Library of Celsus","rarity":"epic","id":"library-of-celsus","subtitle":"Ancient Site","details":"Built in Ephesus around AD 114 in honour of the Roman senator Celsus, this library's ornate two-storey facade fronted scrolls stored in wall niches.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ephesus_Celsus_Library_Fa%C3%A7ade.jpg?width=1024"},{"name":"Karnak Temple","rarity":"epic","id":"karnak-temple","subtitle":"Ancient Site","details":"Grown over 2,000 years near Luxor, Karnak was Egypt's great temple precinct of Amun-Ra, famed for its forest of carved columns in the Great Hypostyle Hall.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Luxor%2C%20Egypt%2C%20Karnak%2C%20Great%20Hypostyle%20Hall%2C%20Columns%202.jpg?width=1024"},{"name":"Abu Simbel","rarity":"epic","id":"abu-simbel","subtitle":"Ancient Site","details":"Carved into a Nubian cliff around 1264 BC for Pharaoh Ramesses II, Abu Simbel's temples are guarded by four colossal seated statues of the king himself.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Abu%20Simbel%2C%20fa%C3%A7ade%20of%20the%20Great%20Temple%20%286201194723%29.jpg?width=1024"},{"name":"Milan Cathedral","rarity":"epic","id":"milan-cathedral","subtitle":"Cathedral","details":"Begun in 1386, Milan's vast Gothic cathedral is crowned with a forest of marble spires and thousands of statues above the Piazza del Duomo.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Milan%20Cathedral%20from%20Piazza%20del%20Duomo.jpg?width=1024"},{"name":"St. Basil's Cathedral","rarity":"epic","id":"st-basils-cathedral","subtitle":"Cathedral","details":"Commissioned by Ivan the Terrible and completed in 1561 at the edge of Red Square, it is famed for its nine brightly patterned onion domes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sant%20Vasily%20cathedral%20in%20Moscow.JPG?width=1024"},{"name":"Cologne Cathedral","rarity":"epic","id":"cologne-cathedral","subtitle":"Cathedral","details":"Begun in 1248 and completed in 1880 to its medieval plan, this Gothic cathedral in Cologne holds the Shrine of the Three Kings behind its altar.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cologne%20cathedrale%20vue%20sud.jpg?width=1024"},{"name":"Guggenheim Museum Bilbao","rarity":"epic","id":"guggenheim-museum-bilbao","subtitle":"Museum","details":"Frank Gehry's museum, opened in 1997 beside the Nervion River in Bilbao, is sheathed in rippling titanium panels that catch the northern light.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Guggenheim%20Museum%20Bilbao%20%285736586558%29.jpg?width=1024"},{"name":"Fallingwater","rarity":"epic","id":"fallingwater","subtitle":"House","details":"Frank Lloyd Wright designed this house in 1935 over a waterfall in Pennsylvania's Bear Run woods, its concrete terraces floating above the stream.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Wrightfallingwater.jpg?width=1024"},{"name":"The White House","rarity":"epic","id":"the-white-house","subtitle":"Government Building","details":"The official residence of the president of the United States since 1800, this neoclassical mansion in Washington was designed by James Hoban.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/The%20White%20House%20in%20Washington%2C%20DC%20%282012%29.jpg?width=1024"},{"name":"United States Capitol","rarity":"epic","id":"united-states-capitol","subtitle":"Government Building","details":"Crowned by its cast-iron dome, the Capitol in Washington has housed the United States Congress since 1800 and stands at the east end of the Mall.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/US%20Capitol%20west%20side.JPG?width=1024"},{"name":"Grand Central Terminal","rarity":"epic","id":"grand-central-terminal","subtitle":"Building","details":"Opened in 1913 in Midtown Manhattan, this Beaux-Arts rail terminal is famed for its Main Concourse and the celestial mural across its vaulted ceiling.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Grand%20Central%20Station%20Main%20Concourse%20Jan%202006.jpg?width=1024"},{"name":"Flatiron Building","rarity":"epic","id":"flatiron-building","subtitle":"Building","details":"Completed in 1902, this triangular steel-framed tower at Fifth Avenue and Broadway in New York became a landmark of early skyscraper design.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Edificio%20Fuller%20%28Flatiron%29%20en%202010%20desde%20el%20Empire%20State%20crop%20boxin.jpg?width=800"},{"name":"Jefferson Memorial","rarity":"rare","id":"jefferson-memorial","subtitle":"Memorial","details":"Dedicated in Washington in 1943, this domed marble memorial frames a bronze Thomas Jefferson, ringed by words from the Declaration of Independence.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/JeffersonMemorialNightFB.jpg?width=1024"},{"name":"Vietnam Veterans Memorial","rarity":"rare","id":"vietnam-veterans-memorial","subtitle":"Memorial","details":"Maya Lin designed this Washington memorial, dedicated in 1982: two black granite walls sunk into the earth, inscribed with more than 58,000 names.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Vietnam_Veterans_Memorial_reflection_in_low_light.jpg?width=1024"},{"name":"World War II Memorial","rarity":"rare","id":"world-war-ii-memorial","subtitle":"Memorial","details":"Opened in Washington in 2004, this memorial's 56 granite pillars ring a sunken plaza and fountain between the Lincoln Memorial and the obelisk.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Aerial_view_of_National_World_War_II_Memorial.jpg?width=1024"},{"name":"Korean War Veterans Memorial","rarity":"rare","id":"korean-war-veterans-memorial","subtitle":"Memorial","details":"Dedicated in Washington in 1995, this memorial shows 19 stainless steel soldiers on patrol, their reflections doubling in a polished granite wall.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Wall%20of%20Remembrance%20with%20Servicemen%20Statues%20%282110e0e9-95ee-4c5d-8da6-d4e342d577cf%29.JPG?width=800"},{"name":"Crazy Horse Memorial","rarity":"rare","id":"crazy-horse-memorial","subtitle":"Memorial","details":"Begun in the Black Hills in 1948 by Korczak Ziolkowski, this mountain carving of Lakota leader Crazy Horse is planned to stand 172 metres tall.","image":"https://en.wikipedia.org/wiki/Special:FilePath/CrazyHorse.jpg?width=1024"},{"name":"Tian Tan Buddha","rarity":"rare","id":"tian-tan-buddha","subtitle":"Statue","details":"Unveiled in 1993 on Hong Kong's Lantau Island, this bronze Buddha sits 34 metres tall atop 268 steps beside Po Lin Monastery, facing north.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tian_Tan_Buddha_2023081302.jpg?width=1024"},{"name":"Angel of Independence","rarity":"rare","id":"angel-of-independence","subtitle":"Monument","details":"Erected in Mexico City in 1910, this 45-metre victory column carries a gilded winged Angel and holds the remains of independence heroes at its base.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Angel_de_la_independencia170409.jpg?width=1024"},{"name":"Obelisk of Buenos Aires","rarity":"rare","id":"obelisk-of-buenos-aires","subtitle":"Monument","details":"Built in 31 days in 1936 by Alberto Prebisch, this 71-metre obelisk in Buenos Aires marks where the Argentine flag first flew over the city in 1812.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Buenos_Aires_%2820234294752%29.jpg?width=1024"},{"name":"Nelson's Column","rarity":"rare","id":"nelsons-column","subtitle":"Monument","details":"Raised in Trafalgar Square between 1840 and 1843, this 52-metre granite column carries a sandstone statue of Admiral Nelson, who fell at Trafalgar.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Nelson%27s_Column%2C_Trafalgar_Square%2C_London.JPG?width=1024"},{"name":"National Monument (Jakarta)","rarity":"rare","id":"national-monument-jakarta","subtitle":"Monument","details":"Jakarta's National Monument, finished in 1975, is a 132-metre marble obelisk topped by a gold-leaf flame symbolising the struggle for independence.","image":"https://en.wikipedia.org/wiki/Special:FilePath/Jakarta_Indonesia_National-Monument-02.jpg?width=1024"},{"name":"Victor Emmanuel II Monument","rarity":"rare","id":"victor-emmanuel-ii-monument","subtitle":"Monument","details":"Built in Rome between 1885 and 1935 in white marble, this monument honours Victor Emmanuel II, first king of united Italy, with his statue at its heart.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Vittoriano_Altare_della_Patria_2013-09-16.jpg?width=1024"},{"name":"Scott Monument","rarity":"rare","id":"scott-monument","subtitle":"Monument","details":"Edinburgh's Scott Monument, completed in 1846, is a 61-metre Gothic sandstone spire honouring Sir Walter Scott, with 287 steps to its top platforms.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Scott_monument_%284792908988%29.jpg?width=1024"},{"name":"Forth Bridge","rarity":"rare","id":"forth-bridge","subtitle":"Bridge","details":"Scotland's Forth Bridge, opened in 1890, carries the railway over the Firth of Forth on three vast steel cantilevers painted in a distinctive red oxide.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e0/Forth_Bridge_2022.jpg/1280px-Forth_Bridge_2022.jpg"},{"name":"Iron Bridge","rarity":"rare","id":"iron-bridge","subtitle":"Bridge","details":"The Iron Bridge of 1779 crosses the River Severn at Ironbridge Gorge in Shropshire, the first major bridge built entirely from cast iron components.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/92/Iron_Bridge_east_side_in_February_2019_%28cropped%29.jpg/1280px-Iron_Bridge_east_side_in_February_2019_%28cropped%29.jpg"},{"name":"Mackinac Bridge","rarity":"rare","id":"mackinac-bridge","subtitle":"Bridge","details":"Michigan's Mackinac Bridge, opened in 1957, links the state's two peninsulas across the Straits of Mackinac, five miles long including its approaches.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/95/Mackinac_Bridge_2022.jpg/1280px-Mackinac_Bridge_2022.jpg"},{"name":"Verrazzano-Narrows Bridge","rarity":"rare","id":"verrazzano-narrows-bridge","subtitle":"Bridge","details":"The Verrazzano-Narrows Bridge, opened in 1964, carries Interstate 278 over the entrance to New York Harbor between Staten Island and Brooklyn.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/72/Verrazano_Bridge2.jpg/1280px-Verrazano_Bridge2.jpg"},{"name":"Tsing Ma Bridge","rarity":"rare","id":"tsing-ma-bridge","subtitle":"Bridge","details":"Hong Kong's Tsing Ma Bridge, completed in 1997, carries road and rail to Lantau Island, its 1,377-metre main suspension span a landmark of the harbour.","image":"https://upload.wikimedia.org/wikipedia/commons/4/46/Tsing_Ma_Bridge_2.jpg"},{"name":"Oresund Bridge","rarity":"rare","id":"oresund-bridge","subtitle":"Bridge","details":"The Oresund Bridge, opened in 2000, links Denmark and Sweden across the Oresund strait, carrying a motorway above a double-track railway for eight kilometres.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/01/%C3%98resund_Bridge_from_the_air_in_September_2015.jpg/1280px-%C3%98resund_Bridge_from_the_air_in_September_2015.jpg"},{"name":"Confederation Bridge","rarity":"rare","id":"confederation-bridge","subtitle":"Bridge","details":"Canada's Confederation Bridge, opened in 1997, crosses the Northumberland Strait to Prince Edward Island, a 12.9-kilometre concrete box-girder structure.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/dd/Confederation_Bridge_aerial_view_%28from_PEI_side%29.jpg/1280px-Confederation_Bridge_aerial_view_%28from_PEI_side%29.jpg"},{"name":"Stari Most","rarity":"rare","id":"stari-most","subtitle":"Bridge","details":"Mostar's Stari Most, a humped Ottoman stone arch built in 1566, crosses the Neretva River in Bosnia and Herzegovina, famed for its local diving tradition.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d7/Mostar_Old_Town_Panorama_2007.jpg/1280px-Mostar_Old_Town_Panorama_2007.jpg"},{"name":"Bosphorus Bridge","rarity":"rare","id":"bosphorus-bridge","subtitle":"Bridge","details":"Istanbul's Bosphorus Bridge, completed in 1973, was the first crossing over the strait linking Europe and Asia, a steel suspension span of 1,074 metres.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ab/Bosphorus_Bridge_%281973%29_in_Istanbul.jpg/1280px-Bosphorus_Bridge_%281973%29_in_Istanbul.jpg"},{"name":"Willis Tower","rarity":"rare","id":"willis-tower","subtitle":"Tower","details":"Chicago's Willis Tower, completed in 1973 as the Sears Tower, bundles nine square tubes of different heights into a 442-metre frame designed by Fazlur Khan.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sears_Tower%2C_Wacker_Drive_and_Jackson_Boulevard%2C_Chicago%2C_IL_-_54189600901.jpg?width=1024"},{"name":"Transamerica Pyramid","rarity":"rare","id":"transamerica-pyramid","subtitle":"Skyscraper","details":"San Francisco's Transamerica Pyramid, completed in 1972, tapers to a 260-metre point, its white quartz facade flanked by two wings housing extra elevators.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Transamerica_Pyramid_from_Coit_Tower.jpg?width=1024"},{"name":"Tokyo Tower","rarity":"rare","id":"tokyo-tower","subtitle":"Tower","details":"Tokyo Tower, completed in 1958 and painted international orange and white, was modelled on the Eiffel Tower but built taller, at 333 metres, in lighter steel.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tokyo_Tower_2023.jpg?width=1024"},{"name":"Kuala Lumpur Tower","rarity":"rare","id":"kuala-lumpur-tower","subtitle":"Tower","details":"The Kuala Lumpur Tower, completed in 1995, rises 421 metres from a hilltop in a city rainforest reserve, its shaft crowned by a spherical antenna and pod.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kuala_Lumpur_Tower_20250822_%281%29.jpg?width=1024"},{"name":"Stratosphere Tower","rarity":"rare","id":"stratosphere-tower","subtitle":"Tower","details":"Las Vegas's Stratosphere Tower, completed in 1996, tops its 350-metre frame with thrill rides and a jump platform over 260 metres above the famous Strip.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Aerial_view_Casino_Stratosphere_LAS_09_2017_4912.jpg?width=800"},{"name":"Canton Tower","rarity":"rare","id":"canton-tower","subtitle":"Tower","details":"Guangzhou's Canton Tower, completed in 2010, twists and narrows at the waist as it climbs 600 metres, its lattice shell lit in rainbow colours after dark.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Canton_Tower_20241027_%28cropped%29.jpg?width=800"},{"name":"Milad Tower","rarity":"rare","id":"milad-tower","subtitle":"Tower","details":"Tehran's Milad Tower, completed in 2007, is a 435-metre octagonal concrete tower whose twelve-storey head carries observation decks, restaurants and antennas.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Milad%20tower%20in%20iran.jpg?width=1024"},{"name":"Riga Radio and TV Tower","rarity":"rare","id":"riga-radio-and-tv-tower","subtitle":"Tower","details":"The Riga Radio and TV Tower, completed in 1986 on an island in the Daugava River, leans its three legs into a 368-metre tripod of steel and concrete panels.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Riga%2C%20Daugava%20.%20TV%20tower%20%28380m%29%20-%20ainars%20br%C5%ABvelis%20-%20Panoramio.jpg?width=1024"},{"name":"Berlin Television Tower","rarity":"rare","id":"berlin-television-tower","subtitle":"Tower","details":"Berlin's Fernsehturm, completed in 1969 at Alexanderplatz, is a 368-metre television tower whose sphere carries a revolving restaurant and viewing platform.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Berliner_Fernsehturm%2C_Sicht_vom_Neptunbrunnen_-_Berlin_Mitte.jpg?width=1024"},{"name":"Macau Tower","rarity":"rare","id":"macau-tower","subtitle":"Tower","details":"The Macau Tower, completed in 2001, rises 338 metres over the Pearl River Delta and is famed for a bungy jump platform 233 metres above the ground below.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Macau_Tower_CE_Centre.jpg?width=1024"},{"name":"Sydney Tower","rarity":"rare","id":"sydney-tower","subtitle":"Tower","details":"Sydney Tower, completed in 1981, is a 309-metre golden turret rising from the city centre, with observation decks and revolving restaurants inside its crown.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sydney_Tower_%28Centre_Point_Tower%29_seen_from_Queen%27s_Square%2C_Sydney.jpg?width=1024"},{"name":"Blackpool Tower","rarity":"rare","id":"blackpool-tower","subtitle":"Tower","details":"Blackpool Tower, opened in 1894 on the Lancashire seafront, is a 158-metre iron tower modelled on the Eiffel Tower, standing over a ballroom and a circus.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Blackpool_Tower_05082017_%28cropped%29.jpg?width=1024"},{"name":"Bank of China Tower","rarity":"rare","id":"bank-of-china-tower","subtitle":"Tower","details":"Hong Kong's Bank of China Tower, designed by I. M. Pei and completed in 1990, grows in triangular sections to 367 metres, its frame echoing shoots of bamboo.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/HK_Bank_of_China_Tower_2008_%282%29.jpg?width=1024"},{"name":"Chateau de Chambord","rarity":"rare","id":"chateau-de-chambord","subtitle":"Castle","details":"Francis I began this Loire Valley hunting palace in 1519, a Renaissance marvel of 440 rooms crowned by ornate turrets and a famed double-helix staircase.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Aerial_image_of_Ch%C3%A2teau_de_Chambord_%28view_from_the_southeast%29.jpg?width=1024"},{"name":"Mont Saint-Michel","rarity":"rare","id":"mont-saint-michel","subtitle":"Abbey","details":"A fortified abbey rises from a tidal island off Normandy, built from the eighth century upward and crowned by a Gothic abbey church above ramparts.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mont-Saint-Michel_vu_du_ciel.jpg?width=1024"},{"name":"Hohenzollern Castle","rarity":"rare","id":"hohenzollern-castle","subtitle":"Castle","details":"Ancestral seat of the Hohenzollern dynasty, the hilltop castle above Bisingen took its neo-Gothic form in the 1850s under Frederick William IV of Prussia.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Burg_Hohenzollern_10-2016.jpg?width=1024"},{"name":"Alcazar of Segovia","rarity":"rare","id":"alcazar-of-segovia","subtitle":"Castle","details":"Rising like a ship's prow above two rivers in Castile, this fortress-palace of slate spires served Castilian monarchs and inspired fairytale castles.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Panor%C3%A1mica_Oto%C3%B1o_Alc%C3%A1zar_de_Segovia.jpg?width=1024"},{"name":"Malbork Castle","rarity":"rare","id":"malbork-castle","subtitle":"Castle","details":"The Teutonic Order began this Baltic brick fortress in 1274, and it grew into one of the largest castles on earth, a Gothic stronghold beside the Nogat River.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Zesp%C3%B3%C5%82_Zamku_Krzy%C5%BCackiego_MALBORK_01.jpg?width=1024"},{"name":"Osaka Castle","rarity":"rare","id":"osaka-castle","subtitle":"Castle","details":"Toyotomi Hideyoshi began this great Japanese stronghold in 1583; its five-storey main tower, rebuilt in 1931, rises over massive stone walls and moats.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Osaka%20Castle%2C%20Keep%20tower%2C%20South%20view%2020190415%201.jpg?width=1024"},{"name":"Matsumoto Castle","rarity":"rare","id":"matsumoto-castle","subtitle":"Castle","details":"One of Japan's oldest surviving keeps, this black-lacquered castle from the 1590s stands in the Northern Alps and is nicknamed Crow Castle for its dark wings.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Matsumoto_Castle_Keep_Tower.jpg?width=1024"},{"name":"Kronborg Castle","rarity":"rare","id":"kronborg-castle","subtitle":"Castle","details":"Built at Helsingor to command the Oresund strait, this Renaissance castle of the 1570s is remembered as Elsinore, the setting of Shakespeare's Hamlet.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kronborg_April_2026_10.jpg?width=1024"},{"name":"Leeds Castle","rarity":"rare","id":"leeds-castle","subtitle":"Castle","details":"Set on islands in a lake in Kent, this castle began as a Norman stronghold in 1119 and was reshaped over centuries into an elegant moated country residence.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Leeds_castle.JPG?width=1024"},{"name":"Bodiam Castle","rarity":"rare","id":"bodiam-castle","subtitle":"Castle","details":"Sir Edward Dalyngrigge built this moated quadrangular castle in Sussex in 1385, its round corner towers and battlements reflected in a broad defensive lake.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bodiam-castle-10My8-1197.jpg?width=1024"},{"name":"Conwy Castle","rarity":"rare","id":"conwy-castle","subtitle":"Castle","details":"Edward I raised this Welsh fortress in just four years from 1283, its eight massive towers and town walls guarding the Conwy estuary in a complete plan.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Conwy_Castle%2C_water_view1.jpg?width=1024"},{"name":"Harlech Castle","rarity":"rare","id":"harlech-castle","subtitle":"Castle","details":"Built for Edward I from 1282 on a rock above Cardigan Bay, this concentric Welsh castle withstood sieges and inspired the famous song Men of Harlech.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Harlech_Castle_-_Cadw_photograph.jpg?width=1024"},{"name":"Kilkenny Castle","rarity":"rare","id":"kilkenny-castle","subtitle":"Castle","details":"The Butler family home for some six centuries, this Irish castle began in 1195 and was reshaped from a medieval fortress into a Victorian country house.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kilkenny-castle.jpg?width=800"},{"name":"Roman Forum","rarity":"rare","id":"roman-forum","subtitle":"Ancient Site","details":"For centuries the heart of public life in ancient Rome, the Forum gathered temples, basilicas, triumphal arches and the Senate House around one plaza.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Foro_Romano_Musei_Capitolini_Roma.jpg?width=1024"},{"name":"Pompeii","rarity":"rare","id":"pompeii","subtitle":"Ancient Site","details":"A Roman town near Naples, Pompeii was buried by ash from Mount Vesuvius in AD 79, preserving its streets, houses, frescoes and shops for excavation.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Aerial_image_of_Pompeii_and_Mount_Vesuvius_%28view_from_the_southeast%29.jpg?width=1024"},{"name":"Mesa Verde","rarity":"rare","id":"mesa-verde","subtitle":"Ancient Site","details":"Ancestral Pueblo people built elaborate cliff dwellings of sandstone and mortar beneath the alcoves of Colorado's Mesa Verde in the late 12th century.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cliff_Palace-Colorado-Mesa_Verde_NP.jpg?width=1024"},{"name":"Tikal","rarity":"rare","id":"tikal","subtitle":"Ancient Site","details":"A great Maya city in Guatemala's Peten jungle, Tikal raised towering limestone temple-pyramids above its plazas between about AD 200 and 900.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tikal_3.jpg?width=1024"},{"name":"Teotihuacan","rarity":"rare","id":"teotihuacan","subtitle":"Ancient Site","details":"Once one of the largest cities in the ancient Americas, Teotihuacan near Mexico City was laid out around AD 100 with vast pyramids of the Sun and Moon.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/ZA77_Teotihuac%C3%A1n_edo_de_mex_Herberto_de_la_rosa.jpg?width=1024"},{"name":"Palenque","rarity":"rare","id":"palenque","subtitle":"Ancient Site","details":"A Maya city in Chiapas famed for elegant carved limestone temples, Palenque flourished in the 7th century under the king K'inich Janaab' Pakal.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Temple%20of%20Inscriptions%2C%20Palenque%20%282088170629%29.jpg?width=1024"},{"name":"Gobekli Tepe","rarity":"rare","id":"gobekli-tepe","subtitle":"Ancient Site","details":"Built in southeastern Turkey around 9500 BC, Gobekli Tepe's carved T-shaped stone pillars form some of the oldest known monumental ritual enclosures.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/G%C3%B6bekli_Tepe%2C_Urfa.jpg?width=1024"},{"name":"Newgrange","rarity":"rare","id":"newgrange","subtitle":"Ancient Site","details":"Built in Ireland's Boyne Valley around 3200 BC, Newgrange is a great passage tomb whose chamber is lit by the winter solstice sunrise through a roof box.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Irelands_history.jpg?width=1024"},{"name":"Avebury","rarity":"rare","id":"avebury","subtitle":"Ancient Site","details":"Built in Wiltshire between about 2850 and 2200 BC, Avebury's vast stone circles and earthen henge enclose a village amid the sarsen stones of the avenues.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Wiltshire-Avebury.jpg?width=1024"},{"name":"Luxor Temple","rarity":"rare","id":"luxor-temple","subtitle":"Ancient Site","details":"Built mainly under Amenhotep III and Ramesses II from about 1400 BC, Luxor Temple lines the Nile with colossal statues, pylons and an avenue of sphinxes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/1550_bis_1070_v._Chr._ca._wurde_der_Tempel_von_Luxor_erbaut._01.jpg?width=1024"},{"name":"Jerash","rarity":"rare","id":"jerash","subtitle":"Ancient Site","details":"A Greco-Roman city in northern Jordan, Jerash preserves colonnaded streets, theatres and temples built of limestone during the 1st and 2nd centuries AD.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Oval_Plaza_%28Forum_Romanum%2C_Gerasa_-_Jerash%2C_Jordan%29_-_%D8%B3%D8%A7%D8%AD%D8%A9_%D8%A7%D9%84%D9%86%D8%AF%D9%88%D8%A9%2C_%D8%AC%D8%B1%D8%B4.jpg?width=1024"},{"name":"Volubilis","rarity":"rare","id":"volubilis","subtitle":"Ancient Site","details":"A Roman city in Morocco famed for vivid floor mosaics, Volubilis grew rich on olive oil and grain before its grand houses were abandoned in late antiquity.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Volubilis_Longshot_II.jpg?width=1024"},{"name":"St. Paul's Cathedral","rarity":"rare","id":"st-pauls-cathedral","subtitle":"Cathedral","details":"Christopher Wren's great London cathedral, completed in 1710 after the Great Fire, is defined by its layered dome above Ludgate Hill.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/St%20Paul%27s%20Cathedral%20West%20Front%20City%20of%20London%20England%2001.jpg?width=1024"},{"name":"Westminster Abbey","rarity":"rare","id":"westminster-abbey","subtitle":"Cathedral","details":"This Gothic abbey beside Parliament in London, largely dating from the 1200s, has hosted royal coronations since the time of William the Conqueror.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Towers%20of%20Westminster%20Abbey.jpg?width=800"},{"name":"Sacre-Coeur Basilica","rarity":"rare","id":"sacre-coeur-basilica","subtitle":"Cathedral","details":"Built of white travertine atop the Montmartre hill in Paris and consecrated in 1919, this Romano-Byzantine basilica overlooks the whole city.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/1009%20Basilica%20of%20the%20Sacred%20Heart%20of%20Montmartre%20in%20Paris%20at%20night%20Photo%20by%20Giles%20Laurent.jpg?width=1024"},{"name":"Seville Cathedral","rarity":"rare","id":"seville-cathedral","subtitle":"Cathedral","details":"Seville's Gothic cathedral, completed in the early 1500s, rose on the site of a mosque whose minaret survives as the bell tower called La Giralda.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sevilla%20Cathedral%20And%20Giralda%20Tower%20%2825573987%29.jpeg?width=1024"},{"name":"Mosque-Cathedral of Cordoba","rarity":"rare","id":"mosque-cathedral-of-cordoba","subtitle":"Cathedral","details":"Famed for its forest of red-and-white double arches, this Cordoba landmark began as a great mosque in 784 and gained a cathedral at its heart in 1236.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mezquita%20cordoba%20arcos%20flotantes.jpg?width=1024"},{"name":"Blue Mosque","rarity":"rare","id":"blue-mosque","subtitle":"Mosque","details":"Built for Sultan Ahmed I and completed in 1616 in Istanbul, this mosque is named for the blue Iznik tiles that line its grand domed interior.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Exterior%20of%20Sultan%20Ahmed%20I%20Mosque%20in%20Istanbul%2C%20Turkey%20002.jpg?width=1024"},{"name":"Sheikh Zayed Grand Mosque","rarity":"rare","id":"sheikh-zayed-grand-mosque","subtitle":"Mosque","details":"Completed in 2007 in Abu Dhabi, this vast white marble mosque blends Mughal and Moorish design, with 82 domes and seven crystal chandeliers.","image":"https://upload.wikimedia.org/wikipedia/en/7/7d/Sheikh_Zayed_Mosque_view.jpg"},{"name":"Lotus Temple","rarity":"rare","id":"lotus-temple","subtitle":"Temple","details":"Opened in 1986 in New Delhi, this Baha'i house of worship takes the form of a lotus flower formed by 27 freestanding marble-clad petals.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Lotus%20Temple%20in%20New%20Delhi%2003-2016.jpg?width=1024"},{"name":"Shwedagon Pagoda","rarity":"rare","id":"shwedagon-pagoda","subtitle":"Temple","details":"This gilded stupa in Yangon, Myanmar, rises 99 metres over Singuttara Hill and is covered in gold plates topped by a diamond-studded spire.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/20160813%20Shwedagon%20Pagoda%209949%20DxO.jpg?width=1024"},{"name":"Wat Arun","rarity":"rare","id":"wat-arun","subtitle":"Temple","details":"Bangkok's Temple of Dawn rises in a steep Khmer-style prang decorated with porcelain and seashells on the west bank of the Chao Phraya River.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Wat%20Arun%20Temple%20Of%20Dawn%20%28121412175%29.jpeg?width=1024"},{"name":"Itsukushima Shrine","rarity":"rare","id":"itsukushima-shrine","subtitle":"Shrine","details":"Built over the sea off Miyajima Island, this Shinto shrine is famed for its great vermilion torii gate that appears to float at high tide.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Itsukushima-jinja%20torii%20at%20sunset%2C%20Miyajima%2C%20Japan%2C%2020240816%201812%204144.jpg?width=1024"},{"name":"Fushimi Inari Shrine","rarity":"rare","id":"fushimi-inari-shrine","subtitle":"Shrine","details":"At this Kyoto shrine, thousands of vermilion torii gates donated by worshippers form covered trails up the wooded slopes of Mount Inari.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Torii%20path%20with%20lantern%20at%20Fushimi%20Inari%20Taisha%20Shrine%2C%20Kyoto%2C%20Japan.jpg?width=1024"},{"name":"Todai-ji","rarity":"rare","id":"todai-ji","subtitle":"Temple","details":"This Nara temple, founded in 752, houses a great bronze Buddha inside a vast timber hall approached through the towering Nandaimon gate.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Todai-ji%20Daibutsuden%20front%20view%20in%202011.jpg?width=1024"},{"name":"Martin Luther King Jr. Memorial","rarity":"uncommon","id":"martin-luther-king-jr-memorial","subtitle":"Memorial","details":"Opened in Washington in 2011, this granite memorial carves Martin Luther King Jr. emerging from a split stone: a stone of hope from a mountain of despair.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Martin_Luther_King_Jr._Memorial_%28b0cee633-6c18-4bf7-86c9-d830a55373f9%29.jpg?width=1024"},{"name":"Marine Corps War Memorial","rarity":"uncommon","id":"marine-corps-war-memorial","subtitle":"Memorial","details":"Dedicated in 1954 near Arlington, this bronze memorial recreates the 1945 Iwo Jima flag raising, six figures straining to plant a real flagpole.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/2018-10-31_15_25_21_The_west_side_of_the_Marine_Corps_War_Memorial_in_Arlington_County%2C_Virginia.jpg?width=1024"},{"name":"USS Arizona Memorial","rarity":"uncommon","id":"uss-arizona-memorial","subtitle":"Memorial","details":"Straddling the sunken battleship Arizona at Pearl Harbor since 1962, this white memorial honours the 1,177 crewmen lost in the 1941 attack.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Arizona_Memorial_%28aerial_view%29.jpg?width=1024"},{"name":"Tomb of the Unknown Soldier","rarity":"uncommon","id":"tomb-of-the-unknown-soldier","subtitle":"Memorial","details":"At Arlington since 1921, this white marble tomb honours unidentified American war dead; an honor guard keeps watch over it around the clock.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tomb_of_the_Unknown_Soldier_Centennial_Commemoration_Flower_Ceremony_-_Day_One_at_Arlington_National_Cemetery%2C_Arlington%2C_Virginia%2C_November_9%2C_2021_-_2.jpg?width=1024"},{"name":"Franklin Delano Roosevelt Memorial","rarity":"uncommon","id":"franklin-delano-roosevelt-memorial","subtitle":"Memorial","details":"Opened in Washington in 1997, this memorial of granite walls, waterfalls and bronzes unfolds in four outdoor rooms, one for each Roosevelt term.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Washington%20D.C.%20-%20Franklin%20Delano%20Roosevelt%20Memorial%200038.jpg?width=1024"},{"name":"Albert Memorial","rarity":"uncommon","id":"albert-memorial","subtitle":"Memorial","details":"Opened in 1872, London's Albert Memorial seats a gilded Prince Albert under a 54-metre mosaic canopy in Kensington Gardens, facing his concert hall.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Albert_Memorial%2C_London_-_May_2008.jpg?width=1024"},{"name":"Cleopatra's Needle","rarity":"uncommon","id":"cleopatras-needle","subtitle":"Monument","details":"This granite obelisk on London's Embankment was carved in Egypt around 1450 BC for Thutmose III and shipped to Britain in 1877 in an iron cylinder.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Western_Side_of_Cleopatra%27s_Needle_in_London.jpg?width=800"},{"name":"Luxor Obelisk","rarity":"uncommon","id":"luxor-obelisk","subtitle":"Monument","details":"One of a pair raised at Luxor Temple under Ramesses II, this 23-metre granite obelisk has stood in Paris's Place de la Concorde since 1836.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Paris%2C_Obelisk_in_the_Place_de_la_Concorde%2C_July_22%2C_2008.jpg?width=1024"},{"name":"Christ the King Statue (Poland)","rarity":"uncommon","id":"christ-the-king-statue-poland","subtitle":"Monument","details":"Completed in 2010 in Swiebodzin, Poland, this crowned statue of Christ stands 36 metres tall atop a mound, its arms spanning 24 metres.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/%C5%9Awiebodzin%2C_Pomnik_Chrystusa_Kr%C3%B3la_-_fotopolska.eu_%28226301%29.jpg?width=1024"},{"name":"Kamakura Daibutsu","rarity":"uncommon","id":"kamakura-daibutsu","subtitle":"Statue","details":"Cast in bronze in 1252 at Kotoku-in temple in Kamakura, this 13-metre Amida Buddha once stood in a great hall that storms long ago swept away.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Templo_K%C5%8Dtoku-in%2C_Kamakura_-_2026_-_05.jpg?width=1024"},{"name":"Gateway of India","rarity":"uncommon","id":"gateway-of-india","subtitle":"Monument","details":"Built in Mumbai in 1924 to welcome King George V, this 26-metre basalt arch faces the harbour; the last British troops marched through it in 1948.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mumbai_03-2016_30_Gateway_of_India.jpg?width=1024"},{"name":"Patuxai","rarity":"uncommon","id":"patuxai","subtitle":"Monument","details":"Vientiane's Patuxai, built between 1957 and 1968, is a five-towered war memorial in Laotian style, its concrete arches carved with stucco ornament.","image":"https://en.wikipedia.org/wiki/Special:FilePath/Vientiane_-_Patuxai_-_0003.jpg?width=1024"},{"name":"Victory Monument (Bangkok)","rarity":"uncommon","id":"victory-monument-bangkok","subtitle":"Monument","details":"Raised in Bangkok in 1941, this 50-metre marble and bronze obelisk honours Thai war dead, ringed by five statues of the armed services.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Victory%20Monument%20Bangkok%20Thailand%2003.jpg?width=1024"},{"name":"Arch of Triumph (Pyongyang)","rarity":"uncommon","id":"arch-of-triumph-pyongyang","subtitle":"Monument","details":"Built in Pyongyang in 1982 from 25,500 blocks of white granite, this 60-metre arch marks the spot where Kim Il Sung addressed crowds after liberation in 1945.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Arch_of_Triumph_in_Pyongyang%2C_North_Korea.jpg?width=1024"},{"name":"Peace Arch","rarity":"uncommon","id":"peace-arch","subtitle":"Monument","details":"Dedicated in 1921 on the Washington-British Columbia border, this 20-metre white arch celebrates an open border between the two nations.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Peace_Arch_%28Canada%E2%80%93United_States_border%29.jpg?width=1024"},{"name":"Bunker Hill Monument","rarity":"uncommon","id":"bunker-hill-monument","subtitle":"Monument","details":"This 67-metre granite obelisk in Boston, completed in 1843, commemorates the 1775 Battle of Bunker Hill; 294 steps climb to an open chamber at the very top.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bunker_hill_2009.JPG?width=1024"},{"name":"Pilgrim Monument","rarity":"uncommon","id":"pilgrim-monument","subtitle":"Monument","details":"Provincetown's Pilgrim Monument, finished in 1910, is a 77-metre granite tower marking where the Mayflower first anchored in the New World in 1620.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/PilgrimMonumentbasrelief.jpg?width=1024"},{"name":"Mother Armenia","rarity":"uncommon","id":"mother-armenia","subtitle":"Statue","details":"Raised in Yerevan in 1967, this 22-metre copper figure of a woman with a sword stands on a 36-metre pedestal watching over the Armenian capital.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mayr_Hayrenik.jpg?width=1024"},{"name":"Decebalus Rock Sculpture","rarity":"uncommon","id":"decebalus-rock-sculpture","subtitle":"Statue","details":"Carved into a Danube cliff in Romania between 1994 and 2004, this 55-metre rock face of Decebalus, last king of Dacia, gazes across the Iron Gates.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Statuia_Chipul_lui_Decebal_-_Cazanele_Dun%C4%83rii%2C_Rom%C3%A2nia.jpg?width=1024"},{"name":"Clifton Suspension Bridge","rarity":"uncommon","id":"clifton-suspension-bridge","subtitle":"Bridge","details":"The Clifton Suspension Bridge, designed by Isambard Kingdom Brunel and completed in 1864, crosses the Avon Gorge in Bristol 75 metres above the river.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/79/Clifton_Suspension_Bridge-9350.jpg/1280px-Clifton_Suspension_Bridge-9350.jpg"},{"name":"Szechenyi Chain Bridge","rarity":"uncommon","id":"szechenyi-chain-bridge","subtitle":"Bridge","details":"Budapest's Szechenyi Chain Bridge, opened in 1849, was the first permanent bridge across the Danube in Hungary, guarded by stone lions at each abutment.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fd/Sz%C3%A9chenyi_Chain_Bridge_in_Budapest_at_night.jpg/1280px-Sz%C3%A9chenyi_Chain_Bridge_in_Budapest_at_night.jpg"},{"name":"Pont Alexandre III","rarity":"uncommon","id":"pont-alexandre-iii","subtitle":"Bridge","details":"Paris's Pont Alexandre III, opened for the 1900 Exposition, crosses the Seine in a single steel arch, decorated with gilded statues, lamps and cherubs.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a9/Pont_Alexandre_III_depuis_pont_de_la_Concorde_Paris.jpg/1280px-Pont_Alexandre_III_depuis_pont_de_la_Concorde_Paris.jpg"},{"name":"Pont Neuf","rarity":"uncommon","id":"pont-neuf","subtitle":"Bridge","details":"The Pont Neuf, despite its name the oldest surviving bridge in Paris, was completed in 1607, crossing the Seine around the western tip of the Ile de la Cite.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9e/The_western_sides_of_the_%C3%8Ele_de_la_Cit%C3%A9_and_the_Pont_Neuf%2C_14_July_2008.jpg/1280px-The_western_sides_of_the_%C3%8Ele_de_la_Cit%C3%A9_and_the_Pont_Neuf%2C_14_July_2008.jpg"},{"name":"Westminster Bridge","rarity":"uncommon","id":"westminster-bridge","subtitle":"Bridge","details":"London's Westminster Bridge, opened in 1862, carries traffic over the Thames beside the Palace of Westminster, its seven iron arches painted deep green.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b8/Westminster_Bridge_and_Palace_of_Westminster.jpg/1280px-Westminster_Bridge_and_Palace_of_Westminster.jpg"},{"name":"Lake Pontchartrain Causeway","rarity":"uncommon","id":"lake-pontchartrain-causeway","subtitle":"Bridge","details":"The Lake Pontchartrain Causeway in Louisiana, opened in 1956, runs nearly 24 miles across the lake on twin parallel spans of low concrete trestle decking.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fc/Lake_Pontchatrain_Causeway_Aerial_-_Jan2013_%2832382802513%29.jpg/1280px-Lake_Pontchatrain_Causeway_Aerial_-_Jan2013_%2832382802513%29.jpg"},{"name":"Chesapeake Bay Bridge","rarity":"uncommon","id":"chesapeake-bay-bridge","subtitle":"Bridge","details":"The Chesapeake Bay Bridge, opened in 1952, carries US Route 50 across the bay between Annapolis and Maryland's Eastern Shore on twin suspension spans.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b9/Chesapeake_Bay_Bridge_from_Annapolis_to_Maryland%27s_Eastern_Shore_LCCN2011632486-2.jpg/1280px-Chesapeake_Bay_Bridge_from_Annapolis_to_Maryland%27s_Eastern_Shore_LCCN2011632486-2.jpg"},{"name":"Sunshine Skyway Bridge","rarity":"uncommon","id":"sunshine-skyway-bridge","subtitle":"Bridge","details":"Florida's Sunshine Skyway Bridge, opened in 1987, crosses Tampa Bay on a cable-stayed main span, its yellow cables fanning from two tall concrete pylons.","image":"https://upload.wikimedia.org/wikipedia/commons/1/17/SunshineSkywayBridge-4SC_6643-15.jpg"},{"name":"New River Gorge Bridge","rarity":"uncommon","id":"new-river-gorge-bridge","subtitle":"Bridge","details":"West Virginia's New River Gorge Bridge, completed in 1977, is a steel arch spanning 518 metres across the gorge, 267 metres above the river below it.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/11/New_River_Gorge_Bridge.jpg/1280px-New_River_Gorge_Bridge.jpg"},{"name":"Royal Gorge Bridge","rarity":"uncommon","id":"royal-gorge-bridge","subtitle":"Bridge","details":"Colorado's Royal Gorge Bridge, built in 1929, crosses the Arkansas River gorge on a suspension span, its deck about 291 metres above the water below.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ee/Royal_Gorge_Bridge_%28looking_west%29.jpg/1280px-Royal_Gorge_Bridge_%28looking_west%29.jpg"},{"name":"Russky Bridge","rarity":"uncommon","id":"russky-bridge","subtitle":"Bridge","details":"Vladivostok's Russky Bridge, opened in 2012, links the city to Russky Island across the Eastern Bosphorus with a cable-stayed main span of 1,104 metres.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/65/Russky_Bridge_%28October_2024%29-0_2.jpg/1280px-Russky_Bridge_%28October_2024%29-0_2.jpg"},{"name":"Hangzhou Bay Bridge","rarity":"uncommon","id":"hangzhou-bay-bridge","subtitle":"Bridge","details":"China's Hangzhou Bay Bridge, opened in 2008, crosses the mouth of Hangzhou Bay for 36 kilometres, carrying an expressway between Jiaxing and Ningbo.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/54/%E6%9D%AD%E5%B7%9E%E6%B9%BE%E5%A4%A7%E6%A1%A5%E4%B8%8A%E7%9A%84%E9%AB%98%E9%80%9F%E5%B2%9B%E5%BC%8F%E6%9C%8D%E5%8A%A1%E5%8C%BA.jpeg/1280px-%E6%9D%AD%E5%B7%9E%E6%B9%BE%E5%A4%A7%E6%A1%A5%E4%B8%8A%E7%9A%84%E9%AB%98%E9%80%9F%E5%B2%9B%E5%BC%8F%E6%9C%8D%E5%8A%A1%E5%8C%BA.jpeg"},{"name":"London Bridge (Lake Havasu)","rarity":"uncommon","id":"london-bridge-lake-havasu","subtitle":"Bridge","details":"London Bridge in Lake Havasu City, Arizona, was rebuilt stone by stone from the 1831 London original, bought in 1968 and rededicated there in 1971.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9e/20251127_LondonBridge.jpg/1280px-20251127_LondonBridge.jpg"},{"name":"Gateshead Millennium Bridge","rarity":"uncommon","id":"gateshead-millennium-bridge","subtitle":"Bridge","details":"The Gateshead Millennium Bridge, opened in 2001, is a tilting pedestrian bridge over the River Tyne, its arch and deck rotating together to let ships pass.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5c/Newcastle-upon-Tyne-bridges-and-skyline_cropped.jpg/1280px-Newcastle-upon-Tyne-bridges-and-skyline_cropped.jpg"},{"name":"Erasmus Bridge","rarity":"uncommon","id":"erasmus-bridge","subtitle":"Bridge","details":"Rotterdam's Erasmus Bridge, opened in 1996, crosses the Nieuwe Maas on a cable-stayed span, its single angled pylon earning it the nickname the Swan.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ac/Erasmusbrug%2C_September_2019.jpg/1280px-Erasmusbrug%2C_September_2019.jpg"},{"name":"Burj Al Arab","rarity":"uncommon","id":"burj-al-arab","subtitle":"Tower","details":"Dubai's Burj Al Arab, completed in 1999, is a sail-shaped hotel standing 321 metres tall on its own artificial island, its mast reaching over the Gulf shore.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Burj%20al%20Arab%20and%20the%20Beach%20%2814535539076%29.jpg?width=1024"},{"name":"Ping An Finance Centre","rarity":"uncommon","id":"ping-an-finance-centre","subtitle":"Skyscraper","details":"Shenzhen's Ping An Finance Centre, completed in 2017, rises 599 metres to a tapered point, its facade clad in stainless steel and light-coloured stone.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pingan_International_Finance_Center2020.jpg?width=800"},{"name":"Lotte World Tower","rarity":"uncommon","id":"lotte-world-tower","subtitle":"Tower","details":"Seoul's Lotte World Tower, completed in 2017, tapers smoothly to 555 metres and 123 floors, its silhouette inspired by celadon pottery and calligraphy brushes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Seoul%20Skyline%20Night%202018.jpg?width=1024"},{"name":"Merdeka 118","rarity":"uncommon","id":"merdeka-118","subtitle":"Skyscraper","details":"Kuala Lumpur's Merdeka 118, completed in 2023, is a 679-metre tower named for Malaysia's independence, its faceted spire rising beside Stadium Merdeka.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Merdeka_Tower_20241022_-_full_2_%28Cropped%29.jpg?width=1024"},{"name":"Shanghai World Financial Center","rarity":"uncommon","id":"shanghai-world-financial-center","subtitle":"Skyscraper","details":"The Shanghai World Financial Center, completed in 2008, is a 492-metre tower famous for the trapezoidal opening near its top, shaped to relieve wind pressure.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Shanghai_World_Financial_Center_%28March_9th_2024%29_%28cropped2%29.jpg?width=800"},{"name":"International Commerce Centre","rarity":"uncommon","id":"international-commerce-centre","subtitle":"Skyscraper","details":"Hong Kong's International Commerce Centre, completed in 2010, stacks 118 floors to 484 metres and houses a hotel whose pool and bar sit near the very top.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/International_Commerce_Centre_skyscraper%2C_in_West_Kowloon%2C_Hong_Kong_%28Ank_Kumar%29_09.jpg?width=1024"},{"name":"Abraj Al Bait Clock Tower","rarity":"uncommon","id":"abraj-al-bait-clock-tower","subtitle":"Tower","details":"Mecca's Abraj Al Bait Clock Tower, completed in 2012, rises 601 metres behind the Grand Mosque, its giant clock faces visible across the holy city below it.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Abraj_Al_Bait_Tower_2017.jpg?width=1024"},{"name":"Spinnaker Tower","rarity":"uncommon","id":"spinnaker-tower","subtitle":"Tower","details":"Portsmouth's Spinnaker Tower, completed in 2005, is a 170-metre sail-shaped observation tower on the harbour, with glass floors suspended 100 metres up.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gunwharf_Quays_and_the_Spinnaker_Tower_in_March_2012_2.JPG?width=1024"},{"name":"Euromast","rarity":"uncommon","id":"euromast","subtitle":"Tower","details":"Rotterdam's Euromast, built for the 1960 Floriade garden festival, is a 185-metre concrete observation tower topped by a crow's nest and a later space cabin.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Rotterdam_euromast.jpg?width=1024"},{"name":"Calgary Tower","rarity":"uncommon","id":"calgary-tower","subtitle":"Tower","details":"The Calgary Tower, completed in 1968, is a 191-metre concrete observation tower built with a continuous concrete pour that lasted twenty-four full days.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Calgary_Tower_%288033515499%29_straightened_2012.jpg?width=1024"},{"name":"Tower of the Americas","rarity":"uncommon","id":"tower-of-the-americas","subtitle":"Tower","details":"San Antonio's Tower of the Americas, built for the 1968 HemisFair world's fair, rises 230 metres with a revolving restaurant and observation deck up top.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/San_Antonio_May_2018_8_%28Tower_of_the_Americas%29.jpg?width=1024"},{"name":"Reunion Tower","rarity":"uncommon","id":"reunion-tower","subtitle":"Tower","details":"Dallas's Reunion Tower, completed in 1978, is a 171-metre tower topped by a geodesic ball lit by 259 lights that form patterns across the night skyline.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Reunion_Tower_2026.jpg?width=1024"},{"name":"Lakhta Center","rarity":"uncommon","id":"lakhta-center","subtitle":"Skyscraper","details":"St. Petersburg's Lakhta Center, completed in 2019, is a 462-metre tower that twists 90 degrees from base to spire, its facade clad in cold-bent glass panels.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/%D0%9B%D0%B0%D1%85%D1%82%D0%B0_%D1%86%D0%B5%D0%BD%D1%82%D1%80_2021.jpg?width=1024"},{"name":"Turning Torso","rarity":"uncommon","id":"turning-torso","subtitle":"Skyscraper","details":"Malmo's Turning Torso, designed by Santiago Calatrava and completed in 2005, twists nine stacked cubes a full 90 degrees over its 190-metre height in Sweden.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Turning_Torso2.jpg?width=800"},{"name":"Marina Bay Sands","rarity":"uncommon","id":"marina-bay-sands","subtitle":"Skyscraper","details":"Singapore's Marina Bay Sands, completed in 2010, balances a boat-shaped SkyPark with an infinity pool across the top of three 55-storey hotel towers by the bay.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Marina_Bay_Sands_%28I%29.jpg?width=1024"},{"name":"Guangzhou CTF Finance Centre","rarity":"uncommon","id":"guangzhou-ctf-finance-centre","subtitle":"Skyscraper","details":"The Guangzhou CTF Finance Centre, completed in 2016, rises 530 metres with terraced setbacks, and its express lifts travel at 20 metres per second.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Guangzhou_CTF_Finance_Centre_in_2016.jpg?width=1024"},{"name":"Zifeng Tower","rarity":"uncommon","id":"zifeng-tower","subtitle":"Tower","details":"Nanjing's Zifeng Tower, completed in 2010, is a 450-metre stepped tower wrapped in dragon-scale glass panels, topped by an observation deck and a spire.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Zifeng_Tower_from_City_Wall.jpg?width=1024"},{"name":"KK100","rarity":"uncommon","id":"kk100","subtitle":"Skyscraper","details":"Shenzhen's KK100, completed in 2011, is a 442-metre curved-glass tower designed around a spring-and-stream motif drawn from the fountain plaza at its base.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/KK100_exterior_southeast.jpg?width=800"},{"name":"Tianjin CTF Finance Centre","rarity":"uncommon","id":"tianjin-ctf-finance-centre","subtitle":"Skyscraper","details":"The Tianjin CTF Finance Centre, completed in 2019, is a 530-metre tower wrapped in an undulating glass skin that reduces wind loads across its curved form.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tianjin_CTF_Finance_Centre_in_2019.jpg?width=1024"},{"name":"Varso Tower","rarity":"uncommon","id":"varso-tower","subtitle":"Tower","details":"Warsaw's Varso Tower, completed in 2022, rises 310 metres including its spire and carries a public observation terrace and restaurant near its very top.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Varso_Tower_Warsaw_22%28cropped%29.jpg?width=800"},{"name":"Stirling Castle","rarity":"uncommon","id":"stirling-castle","subtitle":"Castle","details":"Commanding a volcanic crag between Highlands and Lowlands, Stirling guarded a key Forth crossing and hosted the coronation of infant Mary, Queen of Scots.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Stirling_Castle_Aerial_Photo.jpg?width=1024"},{"name":"Warwick Castle","rarity":"uncommon","id":"warwick-castle","subtitle":"Castle","details":"William the Conqueror ordered a motte here in 1068, and the stone fortress on the River Avon grew into the grand fortified home of the earls of Warwick.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Warwick_Castle_May_2016.jpg?width=1024"},{"name":"Dover Castle","rarity":"uncommon","id":"dover-castle","subtitle":"Castle","details":"Henry II built the great keep of this Channel fortress in the 1180s, atop Roman and Saxon remains at the closest point between England and continental Europe.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/1_dover_castle_aerial_panorama_2017.jpg?width=1024"},{"name":"Caernarfon Castle","rarity":"uncommon","id":"caernarfon-castle","subtitle":"Castle","details":"Edward I began this Welsh castle in 1283, modelling its banded polygonal towers on Constantinople as a deliberate symbol of imperial rule over conquered Wales.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Caernarfon_Castle_1994.jpg?width=1024"},{"name":"Alnwick Castle","rarity":"uncommon","id":"alnwick-castle","subtitle":"Castle","details":"Home of the Percy family since 1309, this Northumberland border fortress mixes medieval curtain walls and towers with grand nineteenth-century state interiors.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Alnwick_-_Alnwick_Castle_-_30.jpg?width=1024"},{"name":"Bamburgh Castle","rarity":"uncommon","id":"bamburgh-castle","subtitle":"Castle","details":"A fortress has crowned this basalt crag above the North Sea since the sixth century; the Norman keep and restored walls dominate the Northumberland coast.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bamburgh_Castle%2C_beautiful_day.jpg?width=1024"},{"name":"Eilean Donan Castle","rarity":"uncommon","id":"eilean-donan-castle","subtitle":"Castle","details":"On a tidal island where three sea lochs meet in the Scottish Highlands, this picturesque castle was rebuilt in the early twentieth century on medieval ruins.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Eilean_Donan_Castle%2C_Scotland_-_Jan_2011.jpg?width=1024"},{"name":"Kylemore Abbey","rarity":"uncommon","id":"kylemore-abbey","subtitle":"Abbey","details":"Mitchell Henry built this neo-Gothic lakeside castle in Connemara in 1868; Benedictine nuns later made it an abbey, famed for its Victorian walled garden.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kylemore_October_2014-1a.jpg?width=1024"},{"name":"Biltmore Estate","rarity":"uncommon","id":"biltmore-estate","subtitle":"Estate","details":"George Vanderbilt completed this 250-room French Renaissance chateau near Asheville in 1895, its grounds landscaped by Frederick Law Olmsted in the hills.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Biltmore_Estate%2C_2012.jpg?width=1024"},{"name":"Hearst Castle","rarity":"uncommon","id":"hearst-castle","subtitle":"Castle","details":"William Randolph Hearst and architect Julia Morgan built this hilltop California estate from 1919, blending European antiques, twin towers and the Neptune Pool.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hearst_Castle_Casa_Grande_September_2012_panorama_2.jpg?width=1024"},{"name":"Iolani Palace","rarity":"uncommon","id":"iolani-palace","subtitle":"Palace","details":"King Kalakaua completed this ornate Honolulu palace in 1882, the only royal palace on United States soil, built in a distinctive American Florentine style.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Iolani_Palace_%2851872681413%29.jpg?width=1024"},{"name":"Topkapi Palace","rarity":"uncommon","id":"topkapi-palace","subtitle":"Palace","details":"Mehmed II founded this Istanbul palace in 1459 above the Bosphorus; for four centuries it housed Ottoman sultans amid courtyards, treasuries and a harem.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Imperial%20Gate.jpg?width=1024"},{"name":"Dolmabahce Palace","rarity":"uncommon","id":"dolmabahce-palace","subtitle":"Palace","details":"Sultan Abdulmecid I completed this Bosphorus palace in 1856, an opulent European-style residence with a crystal staircase and vast ceremonial hall.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dolmabahce_Istanbul_Turkey.jpg?width=1024"},{"name":"Winter Palace","rarity":"uncommon","id":"winter-palace","subtitle":"Palace","details":"Rastrelli designed this green-and-white Baroque palace in St Petersburg for Empress Elizabeth, completed in 1762 as the Romanov winter residence on the Neva.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/RUS-2016-Aerial-SPB-Winter_Palace_%28crop%29.jpg?width=1024"},{"name":"Catherine Palace","rarity":"uncommon","id":"catherine-palace","subtitle":"Palace","details":"This rococo summer palace at Tsarskoye Selo dazzles with a blue-and-gold facade over 300 metres long and interiors that included the legendary Amber Room.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/%D0%A6%D0%B0%D1%80%D1%81%D0%BA%D0%BE%D0%B5_%D0%A1%D0%B5%D0%BB%D0%BE._%D0%95%D0%BA%D0%B0%D1%82%D0%B5%D1%80%D0%B8%D0%BD%D0%B8%D0%BD%D1%81%D0%BA%D0%B8%D0%B9_%D0%B4%D0%B2%D0%BE%D1%80%D0%B5%D1%86_1.jpg?width=1024"},{"name":"Royal Palace of Madrid","rarity":"uncommon","id":"royal-palace-of-madrid","subtitle":"Palace","details":"Built on the site of the old Alcazar after a fire in 1734, Spain's grandest royal palace holds some 3,418 rooms in Italian Baroque style above the Manzanares.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Palacio_Real_de_Madrid_Julio_2016_%28cropped%29.jpg?width=1024"},{"name":"Caserta Palace","rarity":"uncommon","id":"caserta-palace","subtitle":"Palace","details":"Charles of Bourbon commissioned Vanvitelli's vast palace in 1752, a Versailles rival north of Naples with 1,200 rooms, axial gardens and a grand cascade.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Reggia%20di%20Caserta%20vista%20estesa.jpg?width=1024"},{"name":"Linderhof Palace","rarity":"uncommon","id":"linderhof-palace","subtitle":"Palace","details":"Ludwig II of Bavaria built this intimate rococo palace in the 1870s, his only completed palace, famed for its Venus Grotto and Moorish kiosk.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Linderhof-1.jpg?width=1024"},{"name":"Herrenchiemsee","rarity":"uncommon","id":"herrenchiemsee","subtitle":"Palace","details":"Ludwig II began this island palace on Lake Chiemsee in 1878 as a homage to Versailles, with a Hall of Mirrors longer than the original it was modelled on.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Schloss_Herrenchiemsee.jpg?width=1024"},{"name":"Sanssouci","rarity":"uncommon","id":"sanssouci","subtitle":"Palace","details":"Frederick the Great built this rococo summer retreat above terraced vineyards in Potsdam in the 1740s, a single-storey palace whose name means without cares.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Schloss_Sanssouci_2014.jpg?width=1024"}]});
